import {triangles,gardens} from './gsv.mjs';
export function renderEdges(ctx,w,h,layout,{yaw,pitch,zoom,selected}){const sy=Math.sin(yaw),cy=Math.cos(yaw),sp=Math.sin(pitch),cp=Math.cos(pitch),o=layout.ship.origin,scale=Math.min((w-100)/29000,(h-180)/18000)*zoom,faces=[],polys=[],top=gardens[layout.config.garden].height;
 const proj=p=>{const [x,y,z]=p;return {x:w/2+(x*cy-z*sy)*scale,y:h/2+((x*sy+z*cy)*sp-(y-top)*cp)*scale,depth:(x*sy+z*cy)*cp+(y-top)*sp};};
 const add=(v,color,stroke,id)=>{const p=v.map(proj);faces.push({p,color,stroke,id,depth:p.reduce((s,p)=>s+p.depth,0)/p.length});};
 for(const t of triangles.filter(t=>t.v.some(v=>v[1]<top+2&&v[1]>top-750)))add(t.v,'#45395325','#a67ca82a');
 for(const rail of layout.rails.filter(r=>r.edgeRoute)){ctx.beginPath();rail.path.map(p=>proj(p.map((v,k)=>v+o[k]))).forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.strokeStyle='#80b8ff66';ctx.setLineDash([4,4]);ctx.stroke();ctx.setLineDash([]);}
 for(const r of layout.rooms.filter(r=>r.edgeSection)){const v=r.vertices.map(p=>p.map((v,k)=>v+o[k]));for(const f of [[0,1,2,3],[4,5,6,7],[0,1,5,4],[1,2,6,5],[2,3,7,6],[3,0,4,7]])add(f.map(i=>v[i]),r.id===selected?'#f2d698aa':r.type==='hangar'?'#d5a27d88':'#91d9dc88','#eee1bc',r.id);add(r.aperture.vertices.map(p=>p.map((v,k)=>v+o[k])),r.type==='hangar'?'#0f0e15':'#91d9dc','#eee',r.id);}
 faces.sort((a,b)=>a.depth-b.depth);for(const f of faces){ctx.beginPath();f.p.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=f.color;ctx.fill();ctx.strokeStyle=f.stroke;ctx.lineWidth=.7;ctx.stroke();if(f.id)polys.push({id:f.id,points:f.p});}
 ctx.font='12px sans-serif';ctx.textAlign='center';const occupied=[];for(const r of layout.rooms.filter(r=>r.edgeSection)){const p=proj(r.hullCenter),text=(r.type==='hangar'?'[H] ':'[W] ')+r.name,tw=ctx.measureText(text).width+14;let y=p.y-16;while(occupied.some(q=>Math.abs(q.y-y)<20&&Math.abs(q.x-p.x)<(q.w+tw)/2))y-=22;occupied.push({x:p.x,y,w:tw});ctx.strokeStyle='#a67ca8';ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x,y+7);ctx.stroke();ctx.fillStyle=r.id===selected?'#663e70':'#1b101eee';ctx.fillRect(p.x-tw/2,y-12,tw,20);ctx.fillStyle='#eee';ctx.fillText(text,p.x,y+2);polys.push({id:r.id,points:[{x:p.x-tw/2,y:y-12},{x:p.x+tw/2,y:y-12},{x:p.x+tw/2,y:y+8},{x:p.x-tw/2,y:y+8}]});}
 ctx.textAlign='left';ctx.fillStyle='#aaa';ctx.fillText('Select a hull section, then Third person to inspect. Dashed lines: connecting rail.',18,h-65,w-36);return {polys,scale};}
